"use client"

import React, { useState } from "react"
import { motion, AnimatePresence } from "motion/react"
import { cn } from "@/lib/utils"
import { HugeiconsIcon } from "@hugeicons/react"
import {
  ArrowRight01Icon,
  Tick02Icon,
  ArrowRight02Icon,
} from "@hugeicons/core-free-icons"
import {
  SlideToUnlock,
  SlideToUnlockHandle,
  SlideToUnlockText,
  SlideToUnlockTrack,
} from "./slide-subscribe-unlock"
import { ShimmeringText } from "./slide-subscribe-shimmer"

interface PricingOption {
  id: string
  title: string
  price: string
  trial: string
  yearlyPrice?: string
}

const pricingOptions: PricingOption[] = [
  {
    id: "pro-yearly",
    title: "Annual",
    price: "$9.99/mo",
    trial: "14-day free trial",
    yearlyPrice: "$89.98/yr",
  },
  {
    id: "pro-monthly",
    title: "Monthly",
    price: "$14.99/mo",
    trial: "7-day free trial",
  },
  {
    id: "enterprise",
    title: "Enterprise",
    price: "Custom",
    trial: "Contact for pricing",
  },
]

export default function SlideSubscribe() {
  const [selected, setSelected] = useState<string>("pro-yearly")
  const [isUnlocked, setIsUnlocked] = useState(false)

  const handleUnlock = () => {
    setIsUnlocked(true)
  }

  return (
    <div className="w-full max-w-[380px] space-y-4">
      {/* Main Selection Container */}
      <div className="relative flex h-[302px] flex-col overflow-hidden rounded-2xl bg-muted/60 p-3 shadow-inner">
        <AnimatePresence mode="wait">
          {!isUnlocked ? (
            <motion.div
              key="pricing-list"
              className="flex h-full flex-1 flex-col"
            >
              <div className="relative flex-1 space-y-2">
                {pricingOptions.map((option) => (
                  <PricingCard
                    key={option.id}
                    option={option}
                    isSelected={selected === option.id}
                    onSelect={() => setSelected(option.id)}
                  />
                ))}
              </div>

              {/* Converting Text */}
              <div className="pt-6 pb-2">
                <p className="text-center text-xs font-medium text-zinc-500">
                  Risk-free trial. Cancel anytime with one click.
                </p>
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="success-message"
              className="flex h-full flex-1 flex-col items-center justify-center p-6 text-center"
            >
              <motion.div
                initial={{ scale: 0, rotate: -10 }}
                animate={{ scale: 1, rotate: 0 }}
                transition={{
                  type: "spring",
                  delay: 0.2,
                  stiffness: 200,
                  damping: 15,
                }}
                className="mb-6 flex h-16 w-16 items-center justify-center rounded-full bg-green-500 text-white shadow-lg shadow-green-500/10"
              >
                <HugeiconsIcon
                  icon={Tick02Icon}
                  className="h-8 w-8 stroke-[3]"
                />
              </motion.div>
              <div className="space-y-2">
                <h3 className="text-xl font-medium tracking-tight text-zinc-900 dark:text-white">
                  Subscription Active
                </h3>
                <p className="text-sm text-zinc-500 dark:text-zinc-400">
                  Your Pro trial has started. Check your email for next steps.
                </p>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Action Area */}
      <div className="h-14">
        <AnimatePresence mode="wait">
          {!isUnlocked ? (
            <motion.div
              key="slider"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0, scale: 0.95, filter: "blur(2px)" }}
              transition={{ duration: 0.3 }}
            >
              <SlideToUnlock
                handleWidth={56}
                onUnlock={handleUnlock}
                className="w-full overflow-hidden rounded-2xl bg-primary p-1 shadow-lg ring-0"
              >
                <SlideToUnlockTrack className="relative h-12">
                  <SlideToUnlockHandle className="z-20 h-12 w-14 rounded-xl bg-white text-primary shadow-md">
                    <HugeiconsIcon
                      icon={ArrowRight01Icon}
                      className="h-6 w-6"
                    />
                  </SlideToUnlockHandle>

                  <SlideToUnlockText className="-pl-16 z-10 flex items-center justify-center pr-4 text-base text-primary-foreground">
                    {({ isDragging }) => (
                      <ShimmeringText
                        text={
                          isDragging
                            ? "Release to confirm"
                            : "Slide to start trial"
                        }
                        className="font-medium [--color:rgba(255,255,255,0.4)] [--shimmering-color:rgba(255,255,255,1)]"
                      />
                    )}
                  </SlideToUnlockText>
                </SlideToUnlockTrack>
              </SlideToUnlock>
            </motion.div>
          ) : (
            <motion.button
              key="dashboard-button"
              initial={{ opacity: 0, scale: 0.98 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{
                type: "spring",
                opacity: { duration: 0.3 },
              }}
              onClick={() => setIsUnlocked(false)}
              className={cn(
                "group flex h-14 w-full items-center justify-center gap-2 rounded-2xl font-medium shadow-md",
                "bg-zinc-900 text-white dark:bg-white dark:text-black",
                "[--hover-bg:black] dark:[--hover-bg:#f4f4f5]"
              )}
            >
              <span>Back to Dashboard</span>
              <HugeiconsIcon
                icon={ArrowRight02Icon}
                className="h-5 w-5 transition-transform group-hover:translate-x-1"
              />
            </motion.button>
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}

function PricingCard({
  option,
  isSelected,
  onSelect,
}: {
  option: PricingOption
  isSelected: boolean
  onSelect: () => void
}) {
  return (
    <button
      onClick={onSelect}
      className={cn(
        "group relative flex w-full items-center gap-3 rounded-xl bg-card p-4 text-left transition-all duration-300",
        isSelected
          ? "shadow-[0_4px_20px_-4px_rgba(0,0,0,0.1)]"
          : "hover:bg-card/60"
      )}
    >
      {/* Moving Stroke / Highlight */}
      <AnimatePresence>
        {isSelected && (
          <motion.div
            layoutId="pricing-stroke"
            className="pointer-events-none absolute -inset-[1px] z-50 rounded-xl border-[2px] border-primary"
            initial={false}
            transition={{
              type: "spring",
              duration: 0.6,
              bounce: 0.1,
            }}
          />
        )}
      </AnimatePresence>

      {/* Checkmark Circle */}
      <div
        className={cn(
          "relative z-10 flex h-7 w-7 shrink-0 items-center justify-center rounded-full border-2 transition-all duration-500 ease-out",
          isSelected
            ? "border-primary bg-primary text-primary-foreground"
            : "border-input bg-muted"
        )}
      >
        <AnimatePresence mode="popLayout">
          {isSelected ? (
            <motion.div
              key="checked"
              initial={{ scale: 0.5, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.5, opacity: 0 }}
              transition={{ type: "spring" }}
            >
              <HugeiconsIcon
                icon={Tick02Icon}
                className="h-5 w-5 stroke-[4] will-change-transform"
              />
            </motion.div>
          ) : (
            <motion.div
              key="unchecked"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="h-4 w-4"
            />
          )}
        </AnimatePresence>
      </div>

      <div className="relative z-10 flex-1">
        <div className="mb-0 flex items-baseline justify-between">
          <h3
            className={cn(
              "text-lg font-medium tracking-tight transition-colors duration-300",
              "font-serif",
              isSelected ? "text-foreground" : "text-foreground/90"
            )}
          >
            {option.title}
          </h3>
          <div className="text-right">
            <span className="text-base font-medium tracking-tight text-foreground">
              {option.price}
            </span>
          </div>
        </div>
        <div className="flex items-center justify-between">
          <p className="text-xs font-normal text-muted-foreground">
            {option.trial}
          </p>
          {option.yearlyPrice && (
            <p className="text-xs font-normal text-muted-foreground">
              {option.yearlyPrice}
            </p>
          )}
        </div>
      </div>
    </button>
  )
}

"use client"

import {
  animate,
  motion,
  type MotionValue,
  useMotionValue,
  useTransform,
} from "motion/react"
import type { ComponentProps, ComponentPropsWithoutRef, JSX } from "react"
import { createContext, useCallback, useContext, useRef, useState } from "react"

import { cn } from "@/lib/utils"

type SlideToUnlockContextValue = {
  x: MotionValue<number>
  trackRef: React.RefObject<HTMLDivElement | null>
  isDragging: boolean
  handleWidth: number
  textOpacity: MotionValue<number>
  onDragStart: () => void
  onDragEnd: () => void
}

const SlideToUnlockContext = createContext<SlideToUnlockContextValue | null>(
  null
)

function useSlideToUnlock() {
  const context = useContext(SlideToUnlockContext)
  if (!context) {
    throw new Error(
      `SlideToUnlock components must be used within SlideToUnlock`
    )
  }
  return context
}

export type SlideToUnlockRootProps = ComponentProps<"div"> & {
  /**
   * Width of the drag handle in pixels.
   * @defaultValue 56
   * */
  handleWidth?: number
  /** Called when the handle is dragged fully to the end. */
  onUnlock?: () => void
}

export function SlideToUnlock({
  className,
  handleWidth = 56,
  children,
  onUnlock,
  ...props
}: SlideToUnlockRootProps) {
  const trackRef = useRef<HTMLDivElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const x = useMotionValue(0)

  const fadeDistance = handleWidth
  const textOpacity = useTransform(x, [0, fadeDistance], [1, 0])

  const handleDragStart = useCallback(() => {
    setIsDragging(true)
  }, [])

  const handleDragEnd = useCallback(() => {
    setIsDragging(false)

    const trackWidth = trackRef.current?.offsetWidth || 0
    const maxX = trackWidth - handleWidth

    if (x.get() >= maxX) {
      onUnlock?.()
    } else {
      animate(x, 0, { type: "spring", bounce: 0, duration: 0.25 })
    }
  }, [x, onUnlock, handleWidth])

  return (
    <SlideToUnlockContext.Provider
      value={{
        x,
        trackRef,
        isDragging,
        handleWidth,
        textOpacity,
        onDragStart: handleDragStart,
        onDragEnd: handleDragEnd,
      }}
    >
      <div
        data-slot="slide-to-unlock"
        className={cn(
          "w-54 rounded-xl bg-muted p-1 shadow-inner ring-1 ring-foreground/10 ring-inset",
          className
        )}
        {...props}
      >
        {children}
      </div>
    </SlideToUnlockContext.Provider>
  )
}

export type SlideToUnlockTrackProps = ComponentProps<"div">

export function SlideToUnlockTrack({
  className,
  children,
  ...props
}: SlideToUnlockTrackProps) {
  const { trackRef } = useSlideToUnlock()

  return (
    <div
      ref={trackRef}
      data-slot="track"
      className={cn(
        "relative flex h-10 items-center justify-center",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

export type SlideToUnlockTextProps = Omit<
  ComponentPropsWithoutRef<typeof motion.div>,
  "children"
> & {
  /**
   * Accepts a render function as `children` to react to the dragging state.
   *
   * @example
   * ```tsx
   * <SlideToUnlockText>
   *   {({ isDragging }) => <span>{isDragging ? "Release..." : "Slide to unlock"}</span>}
   * </SlideToUnlockText>
   * ```
   */
  children: JSX.Element | ((props: { isDragging: boolean }) => JSX.Element)
}

export function SlideToUnlockText({
  className,
  children,
  style,
  ...props
}: SlideToUnlockTextProps) {
  const { handleWidth, textOpacity, isDragging } = useSlideToUnlock()

  return (
    <motion.div
      data-slot="text"
      data-dragging={isDragging}
      className={cn("pl-1 text-lg font-medium", className)}
      style={{ marginLeft: handleWidth, opacity: textOpacity, ...style }}
      {...props}
    >
      {typeof children === "function" ? children({ isDragging }) : children}
    </motion.div>
  )
}

export type SlideToUnlockHandleProps = ComponentPropsWithoutRef<
  typeof motion.div
>

export function SlideToUnlockHandle({
  className,
  children,
  style,
  ...props
}: SlideToUnlockHandleProps) {
  const {
    x,
    trackRef,
    onDragStart,
    onDragEnd,
    handleWidth: width,
  } = useSlideToUnlock()

  return (
    <motion.div
      data-slot="handle"
      className={cn(
        "absolute top-0 left-0 flex h-10 cursor-grab items-center justify-center rounded-lg bg-white text-zinc-400 shadow-sm active:cursor-grabbing",
        "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-6",
        className
      )}
      style={{ width, x, ...style }}
      drag="x"
      dragConstraints={trackRef}
      dragElastic={0}
      dragMomentum={false}
      onDragStart={onDragStart}
      onDragEnd={onDragEnd}
      {...props}
    >
      {children ?? (
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" aria-hidden>
          <path
            d="M24 12 12.75 3v4.696H0v8.608h12.75V21z"
            fill="currentColor"
          />
        </svg>
      )}
    </motion.div>
  )
}

"use client"

import type { Variants } from "motion/react"
import { motion } from "motion/react"
import * as React from "react"

import { cn } from "@/lib/utils"

export type ShimmeringTextProps = Omit<
  React.ComponentProps<typeof motion.span>,
  "children"
> & {
  /** The text to render with the shimmering effect. */
  text: string
  /**
   * Duration in seconds for one shimmer cycle.
   * @defaultValue 1 */
  duration?: number
  /**
   * Whether the shimmer animation is paused.
   * @defaultValue false */
  isStopped?: boolean
}

export function ShimmeringText({
  text,
  duration = 1,
  isStopped = false,
  className,
  ...props
}: ShimmeringTextProps) {
  const createCharVariants = React.useCallback(
    (charIndex: number): Variants => ({
      running: {
        color: ["var(--color)", "var(--shimmering-color)", "var(--color)"],
        transition: {
          duration,
          repeat: Infinity,
          repeatType: "loop" as const,
          repeatDelay: text.length * 0.05,
          delay: (charIndex * duration) / text.length,
          ease: "easeInOut",
        },
      },
      stopped: {
        color: "var(--color)",
        transition: {
          duration: duration * 0.5,
          ease: "easeOut",
        },
      },
    }),
    [duration, text.length]
  )

  return (
    <motion.span
      className={cn(
        "inline-block select-none",
        "[--color:var(--muted-foreground)] [--shimmering-color:var(--foreground)]",
        className
      )}
      {...props}
    >
      {text?.split("")?.map((char, i) => (
        <motion.span
          key={i}
          className="inline-block whitespace-pre"
          initial="stopped"
          animate={isStopped ? "stopped" : "running"}
          variants={createCharVariants(i)}
        >
          {char}
        </motion.span>
      ))}
    </motion.span>
  )
}
